/* ============================================
   CODE BLOCK COMPONENT
   Monospace code with an optional header row
   (filename, language) and a copy button.
   Note: the system typeface is Nunito Sans;
   code is the one sanctioned monospace context.
   ============================================ */

.ds-code-block {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-300);
  background-color: var(--color-bg-container-primary);
  overflow: hidden;
  max-height: var(--ds-code-block-max-height, none);
}

/* ============================================
   HEADER
   ============================================ */

.ds-code-block__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-200);
  padding: var(--padding-150) var(--padding-200) var(--padding-150) var(--padding-400);
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
  flex-shrink: 0;
  transition: border-bottom-color var(--motion-duration-slow) var(--motion-ease-standard);
}

/* Collapsed: keep the header's height but hide its divider so it
   doesn't double up with the root border */
.ds-code-block--collapsed .ds-code-block__header {
  border-bottom-color: transparent;
}

.ds-code-block__meta {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  min-width: 0;
}

.ds-code-block__toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: var(--padding-050);
  border: none;
  border-radius: var(--radius-pill);
  background: none;
  color: var(--color-icon-primary);
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-code-block__toggle .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
  line-height: 1;
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-code-block--collapsed .ds-code-block__toggle .material-symbols-rounded {
  transform: rotate(-90deg);
}

.ds-code-block__toggle:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-code-block__toggle:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-code-block__filename {
  font-family: var(--font-family-code);
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-code-block__language {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-line-height);
  text-transform: uppercase;
  letter-spacing: var(--font-overline-letter-spacing);
  color: var(--color-text-tertiary);
  flex-shrink: 0;
}

/* ============================================
   COPY BUTTON
   ============================================ */

.ds-code-block__copy {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-100);
  margin: 0;
  padding: var(--padding-050) var(--padding-200);
  border: none;
  border-radius: var(--radius-pill);
  background: none;
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  color: var(--color-text-secondary);
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard), color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-code-block__copy .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
  line-height: 1;
}

.ds-code-block__copy:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-code-block__copy:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* ============================================
   CODE AREA
   ============================================ */

/* Same collapse technique as Accordion: animate the grid track
   between 0fr and 1fr so height animates without measuring */
.ds-code-block__panel {
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows var(--motion-duration-slow) var(--motion-ease-standard);
  min-height: 0;
}

.ds-code-block--collapsed .ds-code-block__panel {
  grid-template-rows: 0fr;
}

.ds-code-block__panel-inner {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.ds-code-block__pre {
  margin: 0;
  padding: var(--padding-400);
  overflow: auto;
  /* Allow the pre to shrink below its content height so a
     max-height on the root scrolls here, not past the header */
  flex: 1 1 auto;
  min-height: 0;
}

.ds-code-block__code {
  font-family: var(--font-family-code);
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-primary);
  white-space: pre;
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-code-block .material-symbols-rounded {
  color: inherit;
}

'use client';

import { useId, useState, type CSSProperties } from 'react';
import { MOTION_FEEDBACK_RESET_MS } from '../../tokens/motion';
import './CodeBlock.css';
import '../../fonts/material-symbols.css';

export interface CodeBlockProps {
  /** The code to display, as a plain string */
  code: string;
  /** Language tag shown in the header, e.g. "tsx", "css" */
  language?: string;
  /** Filename shown in the header, e.g. "tokens-light.css" */
  filename?: string;
  /** Show the copy-to-clipboard button */
  showCopy?: boolean;
  /** Max height of the block; code scrolls vertically inside while the header stays pinned. Numbers are px. */
  maxHeight?: number | string;
  /** Show a chevron beside the filename that collapses/expands the code area */
  collapsible?: boolean;
  /** Start collapsed (only applies when collapsible) */
  defaultCollapsed?: boolean;
  /** Additional CSS classes */
  className?: string;
}

/**
 * CodeBlock component — monospace code with an optional header row
 * (filename, language tag) and a copy-to-clipboard button.
 */
export const CodeBlock = ({
  code,
  language,
  filename,
  showCopy = true,
  maxHeight,
  collapsible = false,
  defaultCollapsed = false,
  className = '',
}: CodeBlockProps) => {
  const baseClass = 'ds-code-block';
  const [copied, setCopied] = useState(false);
  const [collapsed, setCollapsed] = useState(collapsible && defaultCollapsed);
  const panelId = useId();

  const classes = [
    baseClass,
    collapsed ? `${baseClass}--collapsed` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');
  const style =
    maxHeight !== undefined
      ? ({
          '--ds-code-block-max-height':
            typeof maxHeight === 'number' ? `${maxHeight}px` : maxHeight,
        } as CSSProperties)
      : undefined;
  const hasHeader = Boolean(filename || language || showCopy || collapsible);

  const copy = () => {
    // Textarea fallback for contexts where the async clipboard API is
    // unavailable or permission-gated (embedded browsers, http)
    const fallback = () => {
      const textarea = document.createElement('textarea');
      textarea.value = code;
      textarea.setAttribute('readonly', '');
      textarea.style.position = 'absolute';
      textarea.style.left = '-9999px';
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
    };

    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(code).catch(fallback);
    } else {
      fallback();
    }

    setCopied(true);
    window.setTimeout(() => setCopied(false), MOTION_FEEDBACK_RESET_MS);
  };

  return (
    <div className={classes} style={style}>
      {hasHeader && (
        <div className={`${baseClass}__header`}>
          <div className={`${baseClass}__meta`}>
            {collapsible && (
              <button
                type="button"
                className={`${baseClass}__toggle`}
                onClick={() => setCollapsed((c) => !c)}
                aria-expanded={!collapsed}
                aria-controls={panelId}
                aria-label={collapsed ? 'Expand code' : 'Collapse code'}
              >
                <span className="material-symbols-rounded" aria-hidden="true">
                  expand_more
                </span>
              </button>
            )}
            {filename && <code className={`${baseClass}__filename`}>{filename}</code>}
            {language && <span className={`${baseClass}__language`}>{language}</span>}
          </div>
          {showCopy && (
            <button
              type="button"
              className={`${baseClass}__copy`}
              onClick={copy}
              aria-label={copied ? 'Copied' : 'Copy code'}
            >
              <span className="material-symbols-rounded" aria-hidden="true">
                {copied ? 'check' : 'content_copy'}
              </span>
              {copied ? 'Copied' : 'Copy'}
            </button>
          )}
        </div>
      )}
      <div id={panelId} className={`${baseClass}__panel`} aria-hidden={collapsed || undefined}>
        <div className={`${baseClass}__panel-inner`}>
          {/*
            tabIndex + an accessible name make the scroll container reachable:
            long lines scroll horizontally, and without a tab stop a keyboard
            user has no way to reach that scroll.
          */}
          <pre
            className={`${baseClass}__pre`}
            // -1 while collapsed: the panel is aria-hidden then, and a focusable
            // element inside aria-hidden content is unreachable yet still tabbable.
            tabIndex={collapsed ? -1 : 0}
            role="region"
            aria-label={filename ? `Code: ${filename}` : language ? `Code: ${language}` : 'Code'}
          >
            <code className={`${baseClass}__code`}>{code}</code>
          </pre>
        </div>
      </div>
    </div>
  );
};
